#!/usr/bin/env python3
# gate-patch-v7.py — Mission Control gate into Deny 401 (R4es7I5lGGySML1I)
import json,base64,urllib.request,hashlib
JWT="__JWT__"
WID="R4es7I5lGGySML1I"
API="http://localhost:5678/api/v1/workflows/"+WID
HTML=base64.b64decode("").decode("utf-8")
print("gate bytes:",len(HTML),"md5:",hashlib.md5(HTML.encode()).hexdigest())
wf=json.loads(urllib.request.urlopen(urllib.request.Request(API,headers={"X-N8N-API-KEY":JWT})).read())
hit=False
for n in wf["nodes"]:
    if n["name"]=="Deny 401":
        n["parameters"]["responseBody"]=HTML
        hit=True
assert hit,"Deny 401 node not found"
payload=json.dumps({"name":wf["name"],"nodes":wf["nodes"],"connections":wf["connections"],"settings":wf.get("settings",{})}).encode()
r=json.loads(urllib.request.urlopen(urllib.request.Request(API,data=payload,method="PUT",headers={"X-N8N-API-KEY":JWT,"Content-Type":"application/json"})).read())
print("updated:",r.get("id"),"updatedAt:",r.get("updatedAt"))
